<script setup>
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ShieldCheck, KeyRound, UserRound } from '@lucide/vue'
import { auth, roleLabels, signOut } from '../composables/auth'
import { api, resetCsrf } from '../api'
const router=useRouter(), busy=ref(false), error=ref(''), form=reactive({currentPassword:'',newPassword:''})
async function logout(){busy.value=true;error.value='';try{await signOut();await router.replace('/login')}catch(e){error.value=e.message}finally{busy.value=false}}
async function change(){busy.value=true;error.value='';try{await api('/auth/password',{method:'POST',body:form});form.currentPassword='';form.newPassword='';auth.user=null;resetCsrf();await router.replace('/login')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="page-heading"><div><p class="eyebrow">YOUR ACCOUNT</p><h1>你的帳號與個人設定</h1><p class="muted">管理登入資訊，安心使用教學工作區。</p></div></section><div class="account-layout"><section class="surface form-surface"><div class="section-title"><h2><UserRound :size="20" />基本資料</h2></div><dl class="profile-details"><div><dt>顯示名稱</dt><dd>{{ auth.user.displayName }}</dd></div><div><dt>電子郵件</dt><dd>{{ auth.user.email }}</dd></div><div><dt>平台管理權限</dt><dd><span class="role-pill">{{ roleLabels[auth.user.role] }}</span></dd></div></dl><button class="button secondary" :disabled="busy" @click="logout">登出並切換帳號</button><p class="field-hint">登出後請使用另一位教師、助教或學生本人的帳號登入。</p><p class="field-hint">如需調整姓名或平台管理權限，請聯絡管理教授。</p></section><section class="surface form-surface"><div class="section-title"><h2><KeyRound :size="20" />變更密碼</h2></div><form class="stack-form" @submit.prevent="change"><label>目前密碼<input v-model="form.currentPassword" type="password" autocomplete="current-password" required /></label><label>新密碼<input v-model="form.newPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="128" placeholder="至少 12 個字元" /></label><p v-if="error" class="error-box" role="alert">{{ error }}</p><button class="button primary" :disabled="busy">{{ busy?'更新中…':'更新並重新登入' }}</button></form><p class="field-hint"><ShieldCheck :size="15" />變更後會登出目前工作階段。</p></section></div></template>
